
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_opbe_d_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_opbe_d", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.373731310069751e+00, -4.291029415884236e+00, -4.175229185599443e+00, -4.014998642909752e+00, -3.797055618210737e+00, -3.507843967087912e+00, -3.137478634043392e+00, -2.686874864214485e+00, -2.177061534126620e+00, -1.649839008356770e+00, -1.126649044226926e+00, -7.533182524966026e-01, -6.505827303641329e-01, -5.376629035390582e-01, -3.931615853138081e-01, -2.569131795516775e-01, -1.492198030338329e-01, -5.948129409124157e-02, -1.318088306369768e-02, -1.483832361410893e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


